cat << 'EOF' > /app/capture.js
const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  try {
    const browser = await puppeteer.launch({ args: ['--no-sandbox', '--disable-setuid-sandbox'] });
    const page = await browser.newPage();

    // Load local HTML file
    await page.goto(`file://${path.resolve(__dirname, 'output/poster.html')}`, { waitUntil: 'networkidle0' });

    // Set viewport to the poster size
    await page.setViewport({ width: 1400, height: 1980, deviceScaleFactor: 2 });

    // Ensure all fonts are loaded
    await page.evaluateHandle('document.fonts.ready');

    // Take screenshot
    await page.screenshot({ path: path.resolve(__dirname, 'output/final_poster.png') });

    console.log('Screenshot saved to output/final_poster.png');
    await browser.close();
  } catch (error) {
    console.error('Error generating screenshot:', error);
    process.exit(1);
  }
})();
EOF

